-- 0040: ogni luogo sa in che castello si trova, dai confini dei nove castelli.
-- I luoghi di OpenStreetMap e di Overture arrivano senza castello (1.078 su 1.103 al 15/10/2026): la pagina di
-- un castello ne mostrava quasi nessuno. Qui i confini ufficiali dei castelli (da OpenStreetMap, tramite Overture
-- Maps, release 2026-09-23.1, licenza ODbL) e:
--   castello_di(lat, lng): il castello che contiene il punto (se è sul confine o appena fuori, il più vicino entro 300 m);
--   un trigger su `luoghi`: chi arriva senza castello lo prende dalla posizione; i luoghi di OSM e Overture che si
--     spostano lo ricalcolano; quelli inseriti a mano o dai titolari tengono quello scelto;
--   un aggiornamento una tantum dei luoghi che non ce l'hanno.
-- DA APPLICARE A MANO dall'SQL Editor (aggiorna i luoghi esistenti):
-- https://raw.githubusercontent.com/jefebcn/739-san-marino/main/supabase/migrations/0040_castelli_confini.sql
--
-- Per tornare indietro:
--   drop trigger if exists luoghi_castello on public.luoghi; drop function if exists public.luoghi_castello();
--   drop function if exists public.castello_di(double precision, double precision); drop table if exists public.castelli_confini;
--   (i castelli già scritti nei luoghi restano: per toglierli
--    update public.luoghi set castello_id = null where fonte in ('osm', 'overture');)

create table if not exists public.castelli_confini (
  castello_id smallint primary key references public.castelli (id),
  osm text not null,               -- la relazione di OpenStreetMap, es. r3012946
  confine extensions.geography(MultiPolygon, 4326) not null,
  aggiornato_il timestamptz not null default now()
);
create index if not exists castelli_confini_gist on public.castelli_confini using gist (confine);
alter table public.castelli_confini enable row level security;
drop policy if exists "confini visibili a tutti" on public.castelli_confini;
create policy "confini visibili a tutti" on public.castelli_confini for select using (true);
grant select on public.castelli_confini to anon, authenticated;

insert into public.castelli_confini (castello_id, osm, confine)
select c.id, c.osm, extensions.st_multi(extensions.st_setsrid(extensions.st_geomfromgeojson(c.g), 4326))::extensions.geography
from (values
