) as c(id, osm, g)
on conflict (castello_id) do update set osm = excluded.osm, confine = excluded.confine, aggiornato_il = now();

-- Il castello di un punto
create or replace function public.castello_di(p_lat double precision, p_lng double precision)
returns smallint language sql stable set search_path = '' as $$
  with p as (select extensions.st_setsrid(extensions.st_makepoint(p_lng, p_lat), 4326)::extensions.geography as g)
  select coalesce(
    (select c.castello_id from public.castelli_confini c, p where extensions.st_covers(c.confine, p.g) limit 1),
    (select c.castello_id from public.castelli_confini c, p where extensions.st_dwithin(c.confine, p.g, 300)
     order by extensions.st_distance(c.confine, p.g) limit 1)
  )
$$;
grant execute on function public.castello_di(double precision, double precision) to anon, authenticated;

-- Chi arriva senza castello lo prende dalla posizione; OSM e Overture lo ricalcolano se il punto si sposta
create or replace function public.luoghi_castello()
returns trigger language plpgsql set search_path = '' as $$
begin
  if new.lat is not null and new.lng is not null and (
       new.castello_id is null
       or (tg_op = 'UPDATE' and new.fonte in ('osm', 'overture') and (new.lat, new.lng) is distinct from (old.lat, old.lng))
     ) then
    new.castello_id := coalesce(public.castello_di(new.lat, new.lng), new.castello_id);
  end if;
  return new;
end $$;
drop trigger if exists luoghi_castello on public.luoghi;
create trigger luoghi_castello before insert or update of lat, lng, castello_id on public.luoghi
  for each row execute function public.luoghi_castello();

-- Una volta sola: i luoghi che non hanno ancora un castello
update public.luoghi l set castello_id = public.castello_di(l.lat, l.lng)
where l.castello_id is null and public.castello_di(l.lat, l.lng) is not null;

-- Controllo: quanti luoghi per castello
select c.nome, count(l.id) as luoghi from public.castelli c left join public.luoghi l on l.castello_id = c.id group by c.id, c.nome order by c.id;
